/**
 * The generated repositories of the entities the oidc adapters work with, running their real sql on
 * an H2 database on memory: the unit tests of those adapters check the whole round trip (filters,
 * mapping, encrypted columns) without a server.
 *
 * <p>
 * The rows the adapters only read (tenants, users, clients) are seeded with plain sql, so a test
 * does not depend on the creation rules of other bounded contexts.
 * </p>
 */
public final class OidcRepositories {
  private final H2Database db = new H2Database();
  private final DataSource dataSource = db.dataSource();
  private final Tracer tracer = OpenTelemetry.noop().getTracer("test");
  private final PendingWritesRegistry pendingWrites = Mockito.mock(PendingWritesRegistry.class);
  private final KeyRingSecretStorage secrets = new KeyRingSecretStorage("", "");
  private final SecretDigester digester = new SecretDigester("", "");
  private final PasswordHasher hasher = new PasswordHasher();

  public H2Database db() {
    return db;
  }

  public DataSource dataSource() {
    return dataSource;
  }

  public KeyRingSecretStorage secrets() {
    return secrets;
  }

  public SecretDigester digester() {
    return digester;
  }

  /** Without replica: the query repositories read from the primary datasource. */
  @SuppressWarnings("unchecked")
  private Instance<DataSource> noReplica() {
    return Mockito.mock(Instance.class);
  }

  public TenantQueryRepositoryAdapter tenants() {
    return new TenantQueryRepositoryAdapter(dataSource, noReplica(), tracer, pendingWrites);
  }

  public UserQueryRepositoryAdapter users() {
    return new UserQueryRepositoryAdapter(dataSource, noReplica(), tracer, pendingWrites, secrets,
        hasher);
  }

  public UserCommandRepositoryAdapter userWriter() {
    return new UserCommandRepositoryAdapter(dataSource, tracer,
        Mockito.mock(UserEventDispatcher.class), pendingWrites, secrets, hasher);
  }

  public OauthClientQueryRepositoryAdapter clients() {
    return new OauthClientQueryRepositoryAdapter(dataSource, noReplica(), tracer, pendingWrites,
        digester);
  }

  public UserScopeConsentQueryRepositoryAdapter consents() {
    return new UserScopeConsentQueryRepositoryAdapter(dataSource, noReplica(), tracer,
        pendingWrites);
  }

  public UserScopeConsentCommandRepositoryAdapter consentWriter() {
    return new UserScopeConsentCommandRepositoryAdapter(dataSource, tracer,
        Mockito.mock(UserScopeConsentEventDispatcher.class), pendingWrites);
  }

  public UserWebauthnCredentialQueryRepositoryAdapter webauthn() {
    return new UserWebauthnCredentialQueryRepositoryAdapter(dataSource, noReplica(), tracer,
        pendingWrites);
  }

  public UserWebauthnCredentialCommandRepositoryAdapter webauthnWriter() {
    return new UserWebauthnCredentialCommandRepositoryAdapter(dataSource, tracer,
        Mockito.mock(UserWebauthnCredentialEventDispatcher.class), pendingWrites);
  }

  public UserMfaEnrollmentCommandRepositoryAdapter mfaEnrollments() {
    return new UserMfaEnrollmentCommandRepositoryAdapter(dataSource, tracer,
        Mockito.mock(UserMfaEnrollmentEventDispatcher.class), pendingWrites, secrets);
  }

  public UserVerificationCodeCommandRepositoryAdapter verificationCodes() {
    return new UserVerificationCodeCommandRepositoryAdapter(dataSource, tracer,
        Mockito.mock(UserVerificationCodeEventDispatcher.class), pendingWrites, digester);
  }

  public ConsentPurposeQueryRepositoryAdapter purposes() {
    return new ConsentPurposeQueryRepositoryAdapter(dataSource, noReplica(), tracer, pendingWrites);
  }

  public UserPurposeConsentQueryRepositoryAdapter purposeConsents() {
    return new UserPurposeConsentQueryRepositoryAdapter(dataSource, noReplica(), tracer,
        pendingWrites);
  }

  public UserPurposeConsentCommandRepositoryAdapter purposeConsentWriter() {
    return new UserPurposeConsentCommandRepositoryAdapter(dataSource, tracer,
        Mockito.mock(UserPurposeConsentEventDispatcher.class), pendingWrites);
  }

  public TenantTermsOfUseQueryRepositoryAdapter termsOfUse() {
    return new TenantTermsOfUseQueryRepositoryAdapter(dataSource, noReplica(), tracer,
        pendingWrites);
  }

  public UserAcceptedTermsOfUseQueryRepositoryAdapter acceptedTerms() {
    return new UserAcceptedTermsOfUseQueryRepositoryAdapter(dataSource, noReplica(), tracer,
        pendingWrites);
  }

  public UserAcceptedTermsOfUseCommandRepositoryAdapter acceptedTermsWriter() {
    return new UserAcceptedTermsOfUseCommandRepositoryAdapter(dataSource, tracer,
        Mockito.mock(UserAcceptedTermsOfUseEventDispatcher.class), pendingWrites);
  }

  /** An enabled tenant; returns its uid. */
  public String tenant(String name) {
    String uid = uid();
    db.execute("INSERT INTO identity_tenant (uid, version, domain, enabled, mark_for_delete, name,"
        + " root) VALUES ('" + uid + "', 1, '" + name + ".test', true, false, '" + name
        + "', false)");
    return uid;
  }

  /** An enabled user of the tenant; returns its uid. */
  public String user(String tenantUid, String name, String email) {
    String uid = uid();
    db.execute("INSERT INTO identity_user (uid, version, email, email_verified, enabled, name,"
        + " password, temporal_password, use_second_factors, tenant) VALUES ('" + uid + "', 1, '"
        + email + "', true, true, '" + name + "', '" + hasher.hash("secret") + "', false, false, '"
        + tenantUid + "')");
    return uid;
  }

  /** An enabled confidential client of the tenant; returns its uid. */
  public String client(String tenantUid, String code, String name) {
    String uid = uid();
    db.execute(
        "INSERT INTO access_oauth_client (uid, version, client_credentials_token_ttl_seconds,"
            + " client_name, code, dpop_bound_access_tokens, enabled, introspection_allowed,"
            + " require_pkce, require_pushed_authorization_requests, subject_type,"
            + " tls_client_certificate_bound_access_tokens, token_endpoint_auth_method, tenant)"
            + " VALUES ('" + uid + "', 1, 300, '" + name + "', '" + code
            + "', false, true, false, false, false, 'PUBLIC', false, 'CLIENT_SECRET_BASIC', '"
            + tenantUid + "')");
    return uid;
  }

  /** The first column of the first row of a query, null without rows. */
  public String value(String sql) {
    try (Connection connection = dataSource.getConnection();
        PreparedStatement statement = connection.prepareStatement(sql);
        ResultSet result = statement.executeQuery()) {
      return result.next() ? result.getString(1) : null;
    } catch (SQLException ex) {
      throw new IllegalStateException(sql, ex);
    }
  }

  public static String uid() {
    return UUID.randomUUID().toString();
  }
}
